import * as React from "react"

import { cn } from "@/lib/utils"

/** An invitation to act, not a mood. Say what is missing and what to do about it. */
function Empty({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="empty" className={cn("db-empty", className)} {...props} />
}

/** Nothing, as a number: a zero cropped to its top half, which is a fermata's arc. Decorative. */
function EmptyFigure({ className, children = "0", ...props }: React.ComponentProps<"p">) {
  return (
    <p data-slot="empty-figure" aria-hidden="true" className={cn("db-empty-figure", className)} {...props}>
      <span>{children}</span>
    </p>
  )
}

function EmptyTitle({ className, ...props }: React.ComponentProps<"p">) {
  return <p data-slot="empty-title" className={cn("db-empty-title", className)} {...props} />
}

function EmptyDescription({ className, ...props }: React.ComponentProps<"p">) {
  return <p data-slot="empty-description" className={cn("db-empty-description", className)} {...props} />
}

function EmptyActions({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="empty-actions" className={cn("db-empty-actions", className)} {...props} />
}

export { Empty, EmptyFigure, EmptyTitle, EmptyDescription, EmptyActions }

@layer components {
  /* ── db-empty ── an invitation, not an apology */
  .db-empty { display: grid; justify-items: start; gap: var(--db-space-4); }
  /* Nothing, as a number: a zero so large it's cropped to its top half, which is a fermata's arc. */
  .db-empty-figure {
    block-size: 0.46em; margin-block-end: var(--db-space-2); overflow: clip;
    font-size: clamp(7rem, 16vw, 13rem); font-weight: 100; font-stretch: 125%; line-height: 0.76;
    color: var(--db-ink); user-select: none;
  }
  .db-empty-figure > span { display: block; transition: translate var(--db-andante) var(--db-exhale); }
  .db-empty:has(.db-btn:is(:hover, :focus-visible)) .db-empty-figure > span { translate: 0 -0.07em; }
  .db-empty-title { margin: 0; font-size: var(--db-f); line-height: var(--db-f-lh); letter-spacing: var(--db-f-tr); font-weight: 200; color: var(--db-ink); }
  .db-empty-description { max-inline-size: 44ch; }
  .db-empty-actions { display: flex; flex-wrap: wrap; gap: var(--db-space-5); }
}
